type Cell = [number, number]; // [x, y]

function cellEquals([x, y]: Cell, [otherX, otherY]: Cell): boolean {
  return x === otherX && y === otherY;
}

function contains(cells: Cell[], cell: Cell): boolean {
  return cells.some((other) => cellEquals(cell, other));
}

function isNeighbor(cell: Cell, other: Cell): boolean {
  const [x, y] = cell;
  const [otherX, otherY] = other;
  return (
    !cellEquals(cell, other) &&
    Math.abs(otherX - x) <= 1 &&
    Math.abs(otherY - y) <= 1
  );
}

function countLiveNeighbors(cell: Cell, liveCells: Cell[]): number {
  return liveCells.filter((other) => isNeighbor(cell, other)).length;
}

function survives(cell: Cell, liveCells: Cell[]): boolean {
  const liveNeighbors = countLiveNeighbors(cell, liveCells);
  return liveNeighbors === 2 || liveNeighbors === 3;
}

function neighborsOf([x, y]: Cell): Cell[] {
  const neighbors: Cell[] = [];
  for (let dx = -1; dx <= 1; dx++) {
    for (let dy = -1; dy <= 1; dy++) {
      if (dx !== 0 || dy !== 0) {
        neighbors.push([x + dx, y + dy]);
      }
    }
  }
  return neighbors;
}

function deadNeighborsOfLiveCells(liveCells: Cell[]): Cell[] {
  const deadNeighbors: Cell[] = [];
  for (const liveCell of liveCells) {
    for (const neighbor of neighborsOf(liveCell)) {
      if (!contains(liveCells, neighbor) && !contains(deadNeighbors, neighbor)) {
        deadNeighbors.push(neighbor);
      }
    }
  }
  return deadNeighbors;
}

export function nextGeneration(liveCells: Cell[]): Cell[] {
  const survivors = liveCells.filter((cell) => survives(cell, liveCells));
  const born = deadNeighborsOfLiveCells(liveCells).filter(
    (cell) => countLiveNeighbors(cell, liveCells) === 3
  );
  return [...survivors, ...born];
}
